def top_k(lst, k):
    sort = []
    while lst: 
        biggest = lst[0]
        for element in lst:
            if element > biggest:
                biggest = element
        lst.remove(biggest)
        sort.append(biggest)
    return sort[:k]

def top_k(lst, k):

    if lst == []:
        return lst

    lower = []
    higher = 0
    while higher < k:
        plist = lst[0]
        for pivot in lst:
            if pivot > plist:
                plist = pivot
        lst.remove(plist)
        lower.append(plist)
        higher = higher + 1
    return lower

