def top_k(lst, k):
	def sortedd(lst):
		for i in range(len(lst)-1):
			for j in range(len(lst)-1):
				if lst[j] < lst[j+1]:
					lst[j], lst[j+1] = lst[j+1], lst[j]
		return lst
	return sortedd(lst)[:k]

